const chatId = String($input.first().json.message.chat.id);
const text = String($input.first().json.message.text || '');
const staticData = $getWorkflowStaticData('global');
if (!staticData.conversations) staticData.conversations = {};
if (!staticData.conversations[chatId]) staticData.conversations[chatId] = [];

const history = staticData.conversations[chatId].slice(-12);
let context = '';
if (history.length) {
  context = history.map(m => `${m.role === 'user' ? 'Paciente' : 'Recepcionista'}: ${m.content}`).join('\n');
}

const userContent = context
  ? `Historico recente da conversa:\n${context}\n\nMensagem atual do paciente:\n${text}`
  : text;

return [{
  json: {
    chatId,
    text,
    userContent,
    history,
  }
}];

const chatId = String($('Preparar Contexto').item.json.chatId);
const userText = String($('Preparar Contexto').item.json.text || '');
let raw = String($json.output?.[0]?.content?.[0]?.text || $json.output || '');

const match = raw.match(/<<<TRIAGEM>>>\s*([\s\S]*?)\s*<<<FIM>>>/);
let lead = null;
let reply = raw;

if (match) {
  reply = raw.replace(match[0], '').trim();
  try {
    lead = JSON.parse(match[1].trim());
  } catch (e) {
    lead = null;
  }
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversations) staticData.conversations = {};
if (!staticData.conversations[chatId]) staticData.conversations[chatId] = [];
staticData.conversations[chatId].push({ role: 'user', content: userText });
staticData.conversations[chatId].push({ role: 'assistant', content: reply });
if (staticData.conversations[chatId].length > 20) {
  staticData.conversations[chatId] = staticData.conversations[chatId].slice(-20);
}

if (lead?.status === 'completo') {
  staticData.conversations[chatId] = [];
}

return [{
  json: {
    chatId,
    output: reply,
    leadCompleto: !!(lead && lead.status === 'completo'),
    nome: lead?.nome || '',
    queixa: lead?.queixa || '',
    horario_preferido: lead?.horario_preferido || '',
    registrado_em: new Date().toISOString(),
  }
}];
